document.addEventListener("DOMContentLoaded",function(){let activeClass="Klasse 3";let activeRun="1. WL";let isGesamt=false;let liveData=[];let lastUpdate="";const gridContainer=document.getElementById('live-grid');const headerBar=document.getElementById('live-header-bar');const eventDate=document.querySelector('.event-date');const liveStatus=document.getElementById('live-status');const classButtons=document.querySelectorAll('#class-filters .btn-filter');const runButtons=document.querySelectorAll('#run-filters .btn-filter');const allBtn=document.querySelector('.btn-filter[data-type="all"]');let nutzerHatGewaehlt=false;classButtons.forEach(btn=>{btn.addEventListener('click',function(){classButtons.forEach(b=>b.classList.remove('active'));if(allBtn)allBtn.classList.remove('active');this.classList.add('active');activeClass=this.innerText.trim();isGesamt=false;nutzerHatGewaehlt=true;renderTable();});});runButtons.forEach(btn=>{btn.addEventListener('click',function(){runButtons.forEach(b=>b.classList.remove('active'));if(allBtn)allBtn.classList.remove('active');this.classList.add('active');activeRun=this.innerText.trim();isGesamt=false;nutzerHatGewaehlt=true;renderTable();});});if(allBtn){allBtn.addEventListener('click',function(){classButtons.forEach(b=>b.classList.remove('active'));runButtons.forEach(b=>b.classList.remove('active'));this.classList.add('active');isGesamt=true;nutzerHatGewaehlt=true;renderTable();});}
const ZEIT_MUSTER=/^(\d{1,3}):([0-5]?\d),(\d{1,2})$/;function parseTimeToMs(timeStr){let treffer=ZEIT_MUSTER.exec((timeStr||"").trim());if(!treffer)return 999999999;let m=parseInt(treffer[1],10);let s=parseInt(treffer[2],10);let hundertstel=parseInt(treffer[3].padEnd(2,'0'),10);return(m*60*1000)+(s*1000)+(hundertstel*10);}
function msToZeit(ms){const hundertstel=Math.round(Math.abs(ms)/10);const m=Math.floor(hundertstel/6000);const s=Math.floor(hundertstel/100)%60;const h=hundertstel%100;return String(m).padStart(2,'0')+':'+
String(s).padStart(2,'0')+','+
String(h).padStart(2,'0');}
function strafeLesbar(fehler){const zahl=/^\((\d+)\)$/.exec(String(fehler||"").trim());return zahl?`+${zahl[1]} s`:String(fehler||"");}
function einzelzeit(driver,lauf){const treffer=liveData.find(d=>vereinfacht(d.lauf)===vereinfacht(lauf)&&String(d.startnummer)===String(driver.startnummer)&&vereinfacht(d.klasse)===vereinfacht(driver.klasse));return treffer?treffer.zeit_total:"";}
function escapeHtml(wert){return String(wert===undefined||wert===null?"":wert).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}
const vereinfacht=t=>(t||"").replace(/\s+/g,'').toUpperCase();function waehleBelegteAnsicht(){if(nutzerHatGewaehlt||isGesamt||liveData.length===0)return;const hatDaten=(klasse,lauf)=>liveData.some(d=>vereinfacht(d.klasse)===vereinfacht(klasse)&&vereinfacht(d.lauf)===vereinfacht(lauf));if(hatDaten(activeClass,activeRun)){nutzerHatGewaehlt=true;return;}
for(const laufBtn of runButtons){for(const klasseBtn of classButtons){const lauf=laufBtn.innerText.trim();const klasse=klasseBtn.innerText.trim();if(!hatDaten(klasse,lauf))continue;runButtons.forEach(b=>b.classList.remove('active'));classButtons.forEach(b=>b.classList.remove('active'));laufBtn.classList.add('active');klasseBtn.classList.add('active');activeRun=lauf;activeClass=klasse;nutzerHatGewaehlt=true;return;}}}
function zeigeHinweis(titel,text,icon){gridContainer.innerHTML=`
            <div class="live-empty">
                <i class="fa-solid ${icon}"></i>
                <h2>${titel}</h2>
                <p>${text}</p>
            </div>`;}
function renderTable(){if(!liveData||liveData.length===0){headerBar.innerHTML=`Live-Timing`;zeigeHinweis("Noch keine Zeiten","Sobald die Zeitnahme an der Strecke läuft, erscheinen die Ergebnisse "+"hier von selbst - die Seite muss nicht neu geladen werden.","fa-stopwatch");return;}
let filteredData;let titel;if(!isGesamt){let normalizedActiveRun=vereinfacht(activeRun);let normalizedActiveClass=vereinfacht(activeClass);filteredData=liveData.filter(d=>vereinfacht(d.klasse)===normalizedActiveClass&&vereinfacht(d.lauf)===normalizedActiveRun);let titleLauf=activeRun;if(activeRun==="1. WL")titleLauf="1. Wertungslauf";if(activeRun==="2. WL")titleLauf="2. Wertungslauf";titel=`${titleLauf} &middot; ${activeClass}`;}else{filteredData=liveData.filter(d=>vereinfacht(d.lauf)==="GESAMT");titel="Gesamtergebnis &middot; alle Klassen";}
filteredData.sort((a,b)=>{return parseTimeToMs(a.zeit_total)-parseTimeToMs(b.zeit_total);});let bestzeit=null;let vorherige=null;filteredData.forEach((driver,index)=>{driver.platz=index+1;const zeit=parseTimeToMs(driver.zeit_total);const gueltig=zeit!==999999999;if(gueltig&&bestzeit===null)bestzeit=zeit;driver._aufErsten=(gueltig&&bestzeit!==null&&index>0)?'+'+msToZeit(zeit-bestzeit):"";driver._aufVordermann=(gueltig&&vorherige!==null&&index>0)?'+'+msToZeit(zeit-vorherige):"";if(gueltig)vorherige=zeit;});headerBar.innerHTML=titel+`<span class="results-count">${filteredData.length} `+`${filteredData.length === 1 ? "Starter" : "Starter"}</span>`;if(filteredData.length===0){headerBar.innerHTML=titel;zeigeHinweis("Für diese Auswahl liegen noch keine Zeiten vor","Wähle eine andere Klasse oder einen anderen Lauf - oder warte, "+"bis diese Gruppe gefahren ist.","fa-filter-circle-xmark");return;}
gridContainer.classList.toggle('result-grid--gesamt',isGesamt);let html=`
            <div class="grid-header grid-header--mitte">Platz</div>
            <div class="grid-header grid-header--mitte">Nr.</div>
            <div class="grid-header">Fahrer &middot; Ortsclub</div>
            ${isGesamt ? '<div class="grid-header grid-header--rechts">1. WL<br>2. WL</div>' : ''}
            <div class="grid-header grid-header--rechts">Gesamtzeit</div>
            <div class="grid-header grid-header--rechts">Differenz<br>Intervall</div>
        `;filteredData.forEach((driver)=>{const ausgefallen=parseTimeToMs(driver.zeit_total)===999999999;let zeitDetail="";if(driver.fehler){zeitDetail=`${escapeHtml(driver.zeit_raw)} `+`<span class="zeit-strafe">${escapeHtml(strafeLesbar(driver.fehler))}</span>`;}else if(ausgefallen&&driver.zeit_raw){zeitDetail=escapeHtml(driver.zeit_raw);}
let rueckstand;if(driver.platz===1){rueckstand=`<span class="diff-fuehrend">Führend</span>`;}else if(driver._aufErsten){rueckstand=`<span class="diff-first">${driver._aufErsten}</span>`+
(driver._aufVordermann?`<span class="diff-prev">${driver._aufVordermann}</span>`:"");}else{rueckstand=`<span class="diff-prev">&ndash;</span>`;}
let laeufeZelle="";if(isGesamt){const wl1=einzelzeit(driver,"1. WL");const wl2=einzelzeit(driver,"2. WL");laeufeZelle=`
                    <div class="cell-laeufe">
                        <span class="lauf-zeit"><span class="lauf-name">1.<span class="lauf-wl"> WL</span></span>${wl1 ? escapeHtml(wl1) : '&ndash;'}</span>
                        <span class="lauf-zeit"><span class="lauf-name">2.<span class="lauf-wl"> WL</span></span>${wl2 ? escapeHtml(wl2) : '&ndash;'}</span>
                    </div>`;}
html+=`
                <div class="driver-row driver-row--platz${driver.platz}">
                    <div class="cell-platz">
                        <span class="platz-badge">${driver.platz}</span>
                    </div>
                    <div class="cell-nr">
                        <span class="startnummer">${escapeHtml(driver.startnummer)}</span>
                    </div>
                    <div class="cell-fahrer">
                        <span class="driver-name">${escapeHtml(driver.name)}</span>
                        <span class="driver-club">${escapeHtml(driver.club)}</span>
                    </div>
                    ${laeufeZelle}
                    <div class="cell-zeit">
                        <span class="zeit-gesamt${ausgefallen ? ' zeit-gesamt--ausfall' : ''}">${escapeHtml(driver.zeit_total)}</span>
                        ${zeitDetail ? `<span class="zeit-detail">${zeitDetail}</span>` : ''}
                    </div>
                    <div class="cell-diff">${rueckstand}</div>
                </div>
            `;});gridContainer.innerHTML=html;}
async function fetchLiveData(){try{const response=await fetch(`../data/livedata.json?t=${new Date().getTime()}`);if(response.ok){const data=await response.json();liveData=Array.isArray(data.results)?data.results:[];lastUpdate=data.last_update||"";if(eventDate&&data.datum)eventDate.innerText=data.datum;if(liveStatus){liveStatus.innerText=lastUpdate?`Stand ${lastUpdate}`:"Warte auf Zeitnahme";}
waehleBelegteAnsicht();renderTable();}}catch(error){console.log("Warte auf Verbindung zur Zeitnahme...");}}
fetchLiveData();setInterval(fetchLiveData,3000);});